/* Suitability score (0-100 scale, before guardrails). */
static inline float lunar_score(const float x[LUNAR_N_FEATURES]) {
  float s = 44.271498f;
  for (uint32_t t = 0; t < REG_GBR_N_TREES; ++t) {
    uint32_t n = REG_GBR_ROOT[t];
  while (REG_GBR_FEAT[n] != 0xFFu) n = (x[REG_GBR_FEAT[n]] <= REG_GBR_THR[n]) ? REG_GBR_LEFT[n] : REG_GBR_RIGHT[n];
    s += REG_GBR_LEAF[n];
  }
  return s;
}

