/* Class probabilities out[3] in order ['Acceptable', 'Hazardous', 'Optimal']. */
static inline void lunar_class_proba(const float x[LUNAR_N_FEATURES], float out[3]) {
  out[0] = out[1] = out[2] = 0.0f;
  for (uint32_t t = 0; t < CLA_CLA_N_TREES; ++t) {
    uint32_t n = CLA_CLA_ROOT[t];
  while (CLA_CLA_FEAT[n] != 0xFFu) n = (x[CLA_CLA_FEAT[n]] <= CLA_CLA_THR[n]) ? CLA_CLA_LEFT[n] : CLA_CLA_RIGHT[n];
    out[0] += CLA_CLA_LEAF[3u*n]; out[1] += CLA_CLA_LEAF[3u*n+1u]; out[2] += CLA_CLA_LEAF[3u*n+2u];
  }
  out[0] /= CLA_CLA_N_TREES; out[1] /= CLA_CLA_N_TREES; out[2] /= CLA_CLA_N_TREES;
}

