/* Ensemble mean and standard deviation (score uncertainty). */
static inline void lunar_uncertainty(const float x[LUNAR_N_FEATURES], float *mean, float *sd) {
  float s = 0.0f, s2 = 0.0f;
  for (uint32_t t = 0; t < UNC_RF_N_TREES; ++t) {
    uint32_t n = UNC_RF_ROOT[t];
  while (UNC_RF_FEAT[n] != 0xFFu) n = (x[UNC_RF_FEAT[n]] <= UNC_RF_THR[n]) ? UNC_RF_LEFT[n] : UNC_RF_RIGHT[n];
    float v = UNC_RF_LEAF[n]; s += v; s2 += v * v;
  }
  *mean = s / UNC_RF_N_TREES; *sd = sqrtf(s2 / UNC_RF_N_TREES - (*mean) * (*mean));
}

